  "files": {
    "neon-motion-chrome/NeonMotionChrome.tsx": "import { useEffect } from 'react';
import type { ReactNode } from 'react';
import { motion, useMotionValue, useScroll, useSpring, useTransform } from 'framer-motion';
import './neon-motion-chrome.css';

type NeonMotionChromeProps = {
  label?: string;
  children?: ReactNode;
};

export function NeonMotionChrome({ label = 'LIVE MOTION CHROME', children }: NeonMotionChromeProps) {
  const pointerX = useMotionValue(-200);
  const pointerY = useMotionValue(-200);
  const springX = useSpring(pointerX, { stiffness: 260, damping: 34, mass: 0.35 });
  const springY = useSpring(pointerY, { stiffness: 260, damping: 34, mass: 0.35 });
  const { scrollYProgress } = useScroll();
  const progressScale = useSpring(scrollYProgress, { stiffness: 180, damping: 32 });
  const scanShift = useTransform(scrollYProgress, [0, 1], ['0%', '100%']);

  useEffect(() => {
    const onPointerMove = (event: PointerEvent) => {
      if (event.pointerType !== 'mouse') return;
      pointerX.set(event.clientX);
      pointerY.set(event.clientY);
    };

    window.addEventListener('pointermove', onPointerMove, { passive: true });
    return () => window.removeEventListener('pointermove', onPointerMove);
  }, [pointerX, pointerY]);

  return (
    <div className="neon-motion-chrome" data-motion-chrome>
      <motion.div
        className="neon-scroll-progress"
        style={{ scaleX: progressScale }}
        aria-hidden="true"
      />
      <motion.div
        className="neon-scanline"
        style={{ backgroundPositionX: scanShift }}
        aria-hidden="true"
      />
      <motion.div
        className="neon-cursor-trail"
        style={{ x: springX, y: springY }}
        aria-hidden="true"
      />
      <div className="neon-motion-chrome__label">{label}</div>
      {children}
    </div>
  );
}
",
    "neon-motion-chrome/neon-motion-chrome.css": ":root {
  --neon-bg: #05030b;
  --neon-gold: #ffd76a;
  --neon-cyan: #61f6ff;
  --neon-pink: #ff4fd8;
  --neon-violet: #9b5cff;
  --neon-ink: #fff8e7;
}

html {
  scrollbar-width: thin;
  scrollbar-color: var(--neon-cyan) rgba(255, 255, 255, .08);
  scroll-behavior: smooth;
}

::-webkit-scrollbar {
  width: 14px;
  height: 14px;
}

::-webkit-scrollbar-track {
  background: rgba(255, 255, 255, .08);
  border-left: 1px solid rgba(255, 255, 255, .08);
}

::-webkit-scrollbar-thumb {
  min-height: 70px;
  border: 3px solid rgba(5, 3, 11, .9);
  border-radius: 999px;
  background: linear-gradient(180deg, var(--neon-gold), var(--neon-cyan), var(--neon-pink));
  box-shadow: 0 0 18px rgba(97, 246, 255, .32), inset 0 0 14px rgba(255, 255, 255, .16);
}

::-webkit-scrollbar-thumb:hover {
  background: linear-gradient(180deg, var(--neon-cyan), var(--neon-gold), var(--neon-pink));
  box-shadow: 0 0 26px rgba(255, 215, 106, .42), 0 0 18px rgba(255, 79, 216, .26);
}

.neon-motion-chrome {
  position: relative;
  isolation: isolate;
  min-height: 100%;
  color: var(--neon-ink);
}

.neon-motion-chrome::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: -2;
  pointer-events: none;
  background:
    linear-gradient(rgba(255, 255, 255, .026) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, .026) 1px, transparent 1px);
  background-size: 42px 42px;
  mask-image: linear-gradient(to bottom, rgba(0, 0, 0, .82), transparent 78%);
}

.neon-scroll-progress {
  position: fixed;
  top: 0;
  left: 0;
  z-index: 90;
  width: 100%;
  height: 4px;
  transform-origin: left center;
  background: linear-gradient(90deg, var(--neon-gold), var(--neon-cyan), var(--neon-pink));
  box-shadow: 0 0 22px rgba(97, 246, 255, .42);
}

.neon-scanline {
  position: fixed;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  opacity: .34;
  background:
    linear-gradient(90deg, transparent, rgba(255, 255, 255, .12), transparent),
    repeating-linear-gradient(180deg, rgba(97, 246, 255, .04) 0 1px, transparent 1px 8px);
  background-size: 38vw 100%, 100% 8px;
  mix-blend-mode: screen;
}

.neon-cursor-trail {
  position: fixed;
  left: -150px;
  top: -150px;
  z-index: 70;
  width: 300px;
  height: 300px;
  border-radius: 50%;
  pointer-events: none;
  background: radial-gradient(circle, rgba(255, 215, 106, .18), rgba(97, 246, 255, .11) 38%, rgba(255, 79, 216, .08) 56%, transparent 72%);
  filter: blur(10px);
  mix-blend-mode: screen;
}

.neon-motion-chrome__label {
  position: fixed;
  right: 18px;
  bottom: 18px;
  z-index: 75;
  max-width: min(280px, calc(100vw - 36px));
  border: 1px solid rgba(255, 215, 106, .28);
  border-radius: 999px;
  padding: 9px 12px;
  background: rgba(5, 3, 11, .72);
  color: rgba(255, 248, 231, .84);
  font-size: 11px;
  font-weight: 900;
  line-height: 1.1;
  letter-spacing: .12em;
  text-transform: uppercase;
  backdrop-filter: blur(14px);
}

.neon-gradient-text {
  background: linear-gradient(92deg, #fff8e7 0%, var(--neon-gold) 30%, var(--neon-cyan) 60%, var(--neon-pink) 86%, #fff8e7 100%);
  background-size: 220% auto;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  text-shadow: none;
  animation: neonTitleShimmer 7s linear infinite;
}

.neon-glow-panel {
  position: relative;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, .14);
  border-radius: 8px;
  background: linear-gradient(180deg, rgba(255, 255, 255, .09), rgba(255, 255, 255, .035));
  box-shadow: 0 24px 80px rgba(0, 0, 0, .42), 0 0 34px rgba(97, 246, 255, .1);
}

.neon-glow-panel::before {
  content: "";
  position: absolute;
  inset: -80% -20%;
  pointer-events: none;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, .18), transparent);
  transform: rotate(18deg);
  animation: neonSweep 7s ease-in-out infinite;
}

.neon-magnetic {
  transition: transform .22s ease, border-color .22s ease, box-shadow .22s ease;
  will-change: transform;
}

.neon-magnetic:hover {
  transform: translateY(-3px) scale(1.015);
  border-color: rgba(97, 246, 255, .62);
  box-shadow: 0 18px 54px rgba(97, 246, 255, .14), 0 0 28px rgba(255, 215, 106, .16);
}

@keyframes neonTitleShimmer {
  from { background-position: 0% center; }
  to { background-position: 220% center; }
}

@keyframes neonSweep {
  0%, 62% { translate: -120% 0; }
  100% { translate: 120% 0; }
}

@media (pointer: coarse), (max-width: 760px) {
  .neon-cursor-trail {
    display: none;
  }

  .neon-motion-chrome__label {
    position: static;
    display: inline-flex;
    margin: 16px;
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: .001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: .001ms !important;
  }

  .neon-cursor-trail,
  .neon-scanline {
    display: none;
  }
}
